c(17, "§3.3 table (verbatim); §8.10", "feature", "What goes wrong with the product: U_PRODUCT_NEG 257 (12.53%, high-priority, mean 1.25; 17.31% non-seeded) (verbatim): " + table("## 3.3 What goes wrong — the product", 0) + " — shallow for the price ('You literally pay to track your own habits'; 'essentially charging 1 euro per page'); generic or poor content ('all the typos and language errors'; a therapist: 'which I would never recommend for a client or do myself'); overwhelming for the ADHD users it targets; preset routines only ('What if I want the routine to include a workout but not meditation?'); forced intentions / rewards / reflections steps; §8.10: editable routines and own habits (REQ_CUSTOM_ROUTINE 18 + NEG_NO_CUSTOM_HABIT 9) — 'the most consistent product request from people who got past the paywall'", "preset routines; thin content", "complaint", "257 (12.53%) 1.25; SHALLOW 102 (4.97%); CONTENT_THIN 57; COMPLEX 49; UX 38; ONBOARD_LONG 29; POPUP 19", "research", "high-priority", "generalisable", ["10813939995","11664580165","11043750732","10800744729","10894127344","11189301426","7766810111"])
